    contextId,
    contextType,
    canceledBy,
    cancellationReasonsTypeId,
    canceledTime || currentDate(),
    roleId,
    driverUserUniqueId,
    shipperUserUniqueId,
    canceledBy,
    currentDate(),
  ];

  await query(sql, values);
  const cancellationDetails = await getCancellationDetails(contextId);

  return {
    message: "success",
    data: {
      canceledJourneyId: canceledJourneyUniqueId,
      cancellationDetails,
    },
  };
};

