/**
 * Creates a JourneyDecision record that formally links a ShipperRequest
 * to a DriverRequest at the moment of company assignment (status 2).
 *
 * This is the canonical join between the shipper's request and the assigned
 * driver's request. Without it, `handleExistingJourney` in the status-
 * verification service cannot resolve the shipper context and would
 * incorrectly reset the DriverRequest back to status 1.
 *
 * Called by: createAssignment, createBulkAssignments, autoAssignBatch.
 * At confirmation (confirmed_by_driver) the same row is updated to status 4.
 *
 * @param {string} shipperRequestUniqueId
 * @param {string} driverRequestUniqueId
 * @param {string} createdByUserUniqueId  — dispatcher / company admin
 * @returns {Promise<string>} journeyDecisionUniqueId
 */
async function createJourneyDecisionForAssignment(
  shipperRequestUniqueId,
  driverRequestUniqueId,
  createdByUserUniqueId,
) {
  // Resolve numeric PKs
  const [[prRow]] = await db().query(
    "SELECT shipperRequestId FROM ShipperRequest WHERE shipperRequestUniqueId = ? LIMIT 1",

    [shipperRequestUniqueId],
  );
  if (!prRow) {
    throw new AppError(
      "Shipper request not found while creating JourneyDecision",
      404,
    );
  }

  const [[drRow]] = await db().query(
    "SELECT driverRequestId FROM DriverRequest WHERE driverRequestUniqueId = ? LIMIT 1",
    [driverRequestUniqueId],
  );
  if (!drRow) {
    throw new AppError(
      "Driver request not found while creating JourneyDecision",
      404,
    );
  }

  // Idempotency: if a JD already exists for this driverRequestId, return it.
  // Option B creates a NEW DriverRequest (old one is soft-deleted), so the new
  // DR will never collide with the cancelled individual JD's old DR.
  const [[existing]] = await db().query(
    "SELECT journeyDecisionUniqueId FROM JourneyDecisions WHERE driverRequestId = ? LIMIT 1",
    [drRow.driverRequestId],
  );
  if (existing) {
    return existing.journeyDecisionUniqueId;
  }

  const journeyDecisionUniqueId = uuidv4();
  await db().query(
    `INSERT INTO JourneyDecisions
      (journeyDecisionUniqueId, shipperRequestId, driverRequestId,
       journeyStatusId, decisionTime, decisionBy,
       journeyDecisionCreatedBy, journeyDecisionCreatedAt)
     VALUES (?, ?, ?, ?, ?, 'admin', ?, ?)`,
    [
      journeyDecisionUniqueId,
      prRow.shipperRequestId,
      drRow.driverRequestId,
      journeyStatusMap.requested, // status 2 — company has requested this driver
      currentDate(),
      createdByUserUniqueId,
      currentDate(),
    ],
  );

  logger.info("JourneyDecision created at assignment time", {
    journeyDecisionUniqueId,
    shipperRequestUniqueId,
    driverRequestUniqueId,
    journeyStatusId: journeyStatusMap.requested,
  });

  return journeyDecisionUniqueId;
}

/**
 * Sends both FCM + WebSocket notification to an assigned driver.
 * Used by createAssignment, createBulkAssignments, and autoAssignBatch
 * so all three paths behave identically.
 *
 * @param {Object} opts
 * @param {string} opts.driverUserUniqueId
 * @param {string} opts.assignmentUniqueId
 * @param {string} opts.driverRequestUniqueId
 * @param {string} opts.shipperRequestUniqueId
 * @param {string} opts.companyBidRequestUniqueId
 */
const notifyAssignedDriver = async (opts) => {
  const {
    driverUserUniqueId,
    assignmentUniqueId,
    driverRequestUniqueId,
    shipperRequestUniqueId,
    companyBidRequestUniqueId,
  } = opts;

  const notificationData = {
    type: "company_driver_assignment",
    assignmentUniqueId,
    driverRequestUniqueId,
    shipperRequestUniqueId,
    companyBidRequestUniqueId,
  };

  // 1. FCM — wakes up the app even when it's in the background
  sendFCMNotificationToUser({
    userUniqueId: driverUserUniqueId,
    roleId: usersRoles.driverRoleId,
    notification: {
      title: "New freight assignment",
      body: "You have been assigned to a freight job. Please confirm or reject.",
    },
    data: notificationData,
  }).catch((e) =>
    logger.error("FCM failed for driver assignment", {
      error: e.message,
      driverUserUniqueId,
      assignmentUniqueId,
    }),
  );

  // 2. WebSocket — instant delivery when app is already open
  try {
    const [userRows] = await db().query(
      "SELECT phoneNumber FROM Users WHERE userUniqueId = ? LIMIT 1",
      [driverUserUniqueId],
    );
    const phoneNumber = userRows?.[0]?.phoneNumber;

    if (phoneNumber) {
      // Call verifyDriverJourneyStatus to get the exact same payload the driver
      // would receive on the next poll — includes shipper, decision, companyAssignment.
      let wsPayload;
      try {
        const statusResult = await verifyDriverJourneyStatus({
          userUniqueId: driverUserUniqueId,
        });
        wsPayload = {
          messageTypes: messageTypes.company_driver_assignment,
          message: "success",
          ...statusResult, // status, driver, shipper, decision, journey, companyAssignment
        };
      } catch (verifyErr) {
        // Fallback: send minimal payload so ResponseHandler still dispatches status=2
        logger.warn(
          "verifyDriverJourneyStatus failed in notifyAssignedDriver, using fallback payload",
          {
            error: verifyErr.message,
            driverUserUniqueId,
          },
        );
        wsPayload = {
          messageTypes: messageTypes.company_driver_assignment,
          message: "success",
          status: journeyStatusMap.requested,
          companyAssignment: {
            assignmentUniqueId,
            driverRequestUniqueId,
            shipperRequestUniqueId,
            companyBidRequestUniqueId,
          },
          driver: null,
          shipper: null,
          journey: null,
          decision: null,
        };
      }

      sendSocketIONotificationToDriver({
        phoneNumber,
        message: wsPayload,
      }).catch((e) =>
        logger.warn(
          "WebSocket failed for driver assignment (driver may be offline)",
          {
            error: e.message,
            driverUserUniqueId,
            assignmentUniqueId,
          },
        ),
      );
    }
  } catch (e) {
    logger.warn("Could not fetch driver phone for WebSocket notification", {
      error: e.message,
      driverUserUniqueId,
    });
  }
};

/**
 * upsertDriverRequest
 * ────────────────────
 * Creates or reuses a DriverRequest row for the given driver at assignment time.
 *
 * **Offline-first design:** A dispatcher can assign a driver even when the driver
 * is offline (no active DriverRequest). In that case a fresh row is inserted with
 * the origin coordinates from the ShipperRequest, so the driver wakes up to a
 * pre-populated job card.
 *
 * **Rules (in order):**
 * 1. Exactly ONE non-deleted DriverRequest exists → UPDATE it in-place and reuse
 *    its UUID. No status filter — works for waiting, offline, or any state.
 * 2. Zero rows (driver offline) or 2+ rows (test pollution) → INSERT a fresh row.
 *
 * @param {Object} opts
 * @param {string} opts.driverUserUniqueId
 * @param {number} opts.newStatusId        - journeyStatusId to set (e.g. requested = 2)
 * @param {number} opts.originLat
 * @param {number} opts.originLng
 * @param {string} opts.originPlace
 * @returns {Promise<string>} The driverRequestUniqueId to link in the assignment.
 */
const upsertDriverRequest = async ({
  driverUserUniqueId,
  newStatusId,
  originLat,
  originLng,
  originPlace,
}) => {
  // Fetch up to 2 rows — no status filter so offline drivers (0 rows) fall through
  // to the INSERT path, and drivers with exactly 1 row are updated in-place.
  const [existingRows] = await db().query(
    `SELECT driverRequestUniqueId, journeyStatusId
     FROM DriverRequest
     WHERE userUniqueId = ?
       AND driverRequestDeletedAt IS NULL
     LIMIT 2`,
    [driverUserUniqueId],
  );

  if (existingRows && existingRows.length === 1) {
    const existingUniqueId = existingRows[0].driverRequestUniqueId;
    const existingStatus   = existingRows[0].journeyStatusId;

    // ── Option B: Cancel individual connection before company assignment ──────
    // If the driver is currently active in an individual journey (status 1–3),
    // cancel their existing JourneyDecision(s) with 'cancelled_by_system' and
    // return the ShipperRequest to 'waiting' so another driver can pick it up.
    // Status 4+ means the shipper already accepted — those are left untouched
    // (company should not steal a driver mid-confirmed journey).
    const activeIndividualStatuses = [
      journeyStatusMap.waiting,    // 1
      journeyStatusMap.requested,  // 2
      journeyStatusMap.acceptedByDriver, // 3
    ];

    if (activeIndividualStatuses.includes(existingStatus)) {
      // Find all active JourneyDecisions for this DriverRequest
      const [activeDecisions] = await db().query(
        `SELECT jd.journeyDecisionUniqueId, jd.shipperRequestId,
                sr.shipperRequestUniqueId
         FROM JourneyDecisions jd
         INNER JOIN DriverRequest dr ON jd.driverRequestId = dr.driverRequestId
         LEFT JOIN ShipperRequest sr ON jd.shipperRequestId = sr.shipperRequestId
         WHERE dr.driverRequestUniqueId = ?
           AND jd.journeyStatusId IN (?, ?, ?)
           AND jd.journeyDecisionDeletedAt IS NULL`,
        [
          existingUniqueId,
          journeyStatusMap.waiting,
          journeyStatusMap.requested,
          journeyStatusMap.acceptedByDriver,
        ],
      );

      if (activeDecisions.length > 0) {
        logger.info("Company assignment: cancelling individual JourneyDecisions for driver", {
          driverUserUniqueId,
          driverRequestUniqueId: existingUniqueId,
          count: activeDecisions.length,
        });

        for (const decision of activeDecisions) {
          // 1. Mark the individual JourneyDecision as replaced by company assignment (status 16)
          await updateData({
            tableName: "JourneyDecisions",
            conditions: { journeyDecisionUniqueId: decision.journeyDecisionUniqueId },
            updateValues: {
              journeyStatusId: journeyStatusMap.replacedByCompanyAssignment,
              journeyDecisionUpdatedAt: currentDate(),
            },
          });

          // 2. Return the individual ShipperRequest back to waiting
          //    so another driver can pick it up
          if (decision.shipperRequestUniqueId) {
            await updateData({
              tableName: "ShipperRequest",
              conditions: { shipperRequestUniqueId: decision.shipperRequestUniqueId },
              updateValues: {
                journeyStatusId: journeyStatusMap.waiting,
                shipperRequestUpdatedAt: currentDate(),
              },
            });

            logger.info("Individual ShipperRequest returned to waiting", {
              shipperRequestUniqueId: decision.shipperRequestUniqueId,
            });
          }

          // 3. Register the cancellation in CanceledJourneys for audit/analytics.
          //    This matches the pattern used by every other cancellation path.
          //    contextType = JourneyDecisions (journey has not started yet)
          //    contextId   = journeyDecisionId (numeric PK, same as requestActions.service.js)
          try {
            const [jdPkRow] = await db().query(
              `SELECT journeyDecisionId, userUniqueId AS shipperUserUniqueId
               FROM JourneyDecisions jd
               INNER JOIN ShipperRequest sr ON jd.shipperRequestId = sr.shipperRequestId
               WHERE jd.journeyDecisionUniqueId = ? LIMIT 1`,
              [decision.journeyDecisionUniqueId],
            );
            const journeyDecisionId       = jdPkRow?.[0]?.journeyDecisionId;
            const shipperUserUniqueId     = jdPkRow?.[0]?.shipperUserUniqueId;

            if (journeyDecisionId) {
              await createCanceledJourney({
                contextId:                 journeyDecisionId,
                contextType:               CANCELED_JOURNEY_CONTEXTS.JOURNEY_DECISIONS,
                canceledBy:                driverUserUniqueId, // driver whose slot is being taken over
                cancellationReasonsTypeId: 19,                 // "App-related technical issue" (admin/system reason)
                roleId:                    usersRoles.driverRoleId,
                driverUserUniqueId,
                shipperUserUniqueId:       shipperUserUniqueId ?? null,
              });
              logger.info("CanceledJourney audit row written for system-cancelled individual JD", {
                journeyDecisionUniqueId: decision.journeyDecisionUniqueId,
                journeyDecisionId,
                driverUserUniqueId,
              });
            }
          } catch (auditErr) {
            // Non-critical — log but do NOT fail the assignment
            logger.warn("Failed to write CanceledJourney audit row (non-blocking)", {
              journeyDecisionUniqueId: decision.journeyDecisionUniqueId,
              error: auditErr.message,
            });
          }
        }

        // ── Soft-delete the old DriverRequest so a NEW one is created ──────────
        // This preserves the cancelled DR + JD pair as historical records.
        // The INSERT path below will create a fresh DR for the company assignment.
        await updateData({
          tableName: "DriverRequest",
          conditions: { driverRequestUniqueId: existingUniqueId },
          updateValues: {
            journeyStatusId: journeyStatusMap.replacedByCompanyAssignment,
            driverRequestDeletedAt: currentDate(),
            driverRequestUpdatedAt: currentDate(),
          },
        });
        logger.info("Old DriverRequest soft-deleted after Option B cancellation", {
          driverRequestUniqueId: existingUniqueId,
          driverUserUniqueId,
        });

        // ── Notify the driver that their individual job was replaced ───────────
        // Fire-and-forget — don't block the assignment transaction.
        // The driver will also receive a company_driver_assignment notification
        // once the new assignment is fully created.
        try {
          const [userRows] = await db().query(
            "SELECT phoneNumber FROM Users WHERE userUniqueId = ? LIMIT 1",
            [driverUserUniqueId],
          );
          const phoneNumber = userRows?.[0]?.phoneNumber;

          // Collect cancelled ShipperRequest details for the driver's UI
          const cancelledShipperRequests = activeDecisions
            .filter(d => d.shipperRequestUniqueId)
            .map(d => d.shipperRequestUniqueId);

          const replacementPayload = {
            messageTypes: messageTypes.individual_replaced_by_company,
            message: "success",
            type: "individual_replaced_by_company",
            cancelledDriverRequestUniqueId: existingUniqueId,
            cancelledShipperRequests,
            journeyStatusId: journeyStatusMap.replacedByCompanyAssignment,
          };

          // 1. FCM — wakes app even in background
          sendFCMNotificationToUser({
            userUniqueId: driverUserUniqueId,
            roleId: usersRoles.driverRoleId,
            notification: {
              title: "Job reassigned by your company",
              body: "Your individual shipper match has been replaced by a company fleet assignment. Open the app to see your new job.",
            },
            data: {
              type: "individual_replaced_by_company",
              cancelledDriverRequestUniqueId: existingUniqueId,
            },
          }).catch(e =>
            logger.warn("FCM failed for individual-replaced notification", {
              error: e.message,
              driverUserUniqueId,
            }),
          );

          // 2. WebSocket — instant delivery when app is open
          if (phoneNumber) {
            sendSocketIONotificationToDriver({
              phoneNumber,
              message: replacementPayload,
            }).catch(e =>
              logger.warn("WebSocket failed for individual-replaced notification (driver may be offline)", {
                error: e.message,
                driverUserUniqueId,
              }),
            );
          }

          logger.info("Replacement notification sent to driver", {
            driverUserUniqueId,
            cancelledDriverRequestUniqueId: existingUniqueId,
            cancelledShipperRequests,
          });
        } catch (notifyErr) {
          // Non-critical — log but do NOT fail the assignment
          logger.warn("Failed to send replacement notification to driver (non-blocking)", {
            error: notifyErr.message,
            driverUserUniqueId,
          });
        }

        // Fall through to the INSERT path below →
      } else {
        // Driver is in active individual status range but has no active JDs —
        // just update the existing DR in-place for the company assignment.
        await updateData({
          tableName: "DriverRequest",
          conditions: { driverRequestUniqueId: existingUniqueId },
          updateValues: {
            journeyStatusId: newStatusId,
            originLatitude: originLat ?? 0,
            originLongitude: originLng ?? 0,
            originPlace: originPlace ?? "Assigned by dispatcher",
            driverRequestUpdatedAt: currentDate(),
          },
        });
        return existingUniqueId;
      }
    } else {
      // Status 4+ (shipper accepted, journey started, etc.) or non-individual status
      // — just update the existing DR in-place for the company assignment.
      await updateData({
        tableName: "DriverRequest",
        conditions: { driverRequestUniqueId: existingUniqueId },
        updateValues: {
          journeyStatusId: newStatusId,
          originLatitude: originLat ?? 0,
          originLongitude: originLng ?? 0,
          originPlace: originPlace ?? "Assigned by dispatcher",
          driverRequestUpdatedAt: currentDate(),
        },
      });
      return existingUniqueId;
    }
  }

  // 0 rows (offline driver) or 2+ rows (stale test data) → INSERT fresh row.
  const result = await createDriverRequest(
    {
      currentLocation: {
        latitude: originLat ?? 0,
        longitude: originLng ?? 0,
        description: originPlace ?? "Assigned by dispatcher",
      },
    },
    driverUserUniqueId,
    newStatusId,
  );

  // createDriverRequest returns existing active rows without inserting when
  // one already exists (activeJourneyStatuses check). Extract the UUID safely.
  const row = result?.data?.[0];
  if (!row?.driverRequestUniqueId) {
    throw new AppError("Failed to create or reuse DriverRequest", 500);
  }
  return row.driverRequestUniqueId;
};

/**
 * findActiveAssignmentForSlot
 * ────────────────────────────
 * Checks whether a given ShipperRequest slot already has a non-terminal
 * CompanyBidVehicleAssignment for the specified bid.
 *
 * "Active" means any status that is NOT a terminal cancel/reject:
 *   assigned | confirmed_by_driver | going_to_loading | journey_started
 *
 * Returns the assignment row if one exists, or null if the slot is free.
 * Used as a duplicate-assignment guard before creating a new assignment.
 *
 * @param {string} companyBidRequestUniqueId
 * @param {string} shipperRequestUniqueId
 * @returns {Promise<Object|null>} existing assignment row or null
 */
async function findActiveAssignmentForSlot(
  companyBidRequestUniqueId,
  shipperRequestUniqueId,
) {
  const [rows] = await db().query(
    `SELECT assignmentUniqueId, assignmentStatus
     FROM CompanyBidVehicleAssignment
     WHERE companyBidRequestUniqueId = ?
       AND shipperRequestUniqueId  = ?
       AND assignmentDeletedAt IS NULL
       AND assignmentStatus NOT IN (
         'rejected_by_driver',
         'cancelled_by_company',
         'cancelled_by_shipper',
         'cancelled_by_driver'
       )
     LIMIT 1`,
    [companyBidRequestUniqueId, shipperRequestUniqueId],
  );
  return rows.length > 0 ? rows[0] : null;
}

/**
 * createAssignment
 * ─────────────────
 * Assigns a driver+vehicle to a freight slot within an accepted bid.
 *
 * **Just-In-Time PR Creation (company_target):**
 * When `shipperRequestUniqueId` is omitted (company_target deferred flow),
 * a new ShipperRequest row is created automatically from the batch metadata.
 * This avoids bulk-creating N rows upfront — even 450,000 vehicles = 0 rows
 * until the dispatcher actually assigns a driver to each slot.
 *
 * **Capacity Guard:**
 * Before creating a new PR, we check that the batch still has free slots
 * (totalVehicles > existing assignments). This prevents over-assignment.
 */
exports.createAssignment = async (data) => {
  const {
    companyBidRequestUniqueId,
    shipperRequestUniqueId: inputPRUniqueId,
    vehicleUniqueId,
    driverUserUniqueId,
    createdByUserUniqueId,
  } = data;

  // Bid must be accepted by shipper
  const bid = await findOne(
    "CompanyBidRequest",
    { companyBidRequestUniqueId },
    "Bid not found",
  );
  if (bid.bidStatus !== "accepted_by_shipper") {
    throw new AppError(
      "Vehicles can only be assigned after the shipper accepts the bid",
      400,
    );
  }

  let shipperRequestUniqueId = inputPRUniqueId;
  let pr;

  if (shipperRequestUniqueId) {
    // ── EAGER PATH: PR already exists (individual_target or pre-created) ───
    pr = await getShipperRequestByUniqueId(
      shipperRequestUniqueId,
      bid.shipperRequestBatchId,
    );
  } else {
    // ── COMPANY-TARGET PATH: Find a free, unassigned ShipperRequest slot ──
    // All rows were bulk-created when the shipper accepted the bid.
    // The dispatcher just needs to claim one that has no active assignment yet.
    const [[freeSlot]] = await db().query(
      `SELECT sr.shipperRequestUniqueId
       FROM ShipperRequest sr
       WHERE sr.shipperRequestBatchId = ?
         AND sr.shipperRequestDeletedAt IS NULL
         AND sr.journeyStatusId = ?
         AND NOT EXISTS (
           SELECT 1 FROM CompanyBidVehicleAssignment a
           WHERE a.shipperRequestUniqueId = sr.shipperRequestUniqueId
             AND a.assignmentDeletedAt IS NULL
             AND a.assignmentStatus NOT IN (
               'rejected_by_driver','cancelled_by_company',
               'cancelled_by_shipper','cancelled_by_driver'
             )
         )
       LIMIT 1`,
      [bid.shipperRequestBatchId, journeyStatusMap.acceptedByShipper],
    );

    if (!freeSlot) {
      throw new AppError(
        `All ${bid.numberOfVehiclesOffered} vehicle slots for this batch have already been assigned.`,
        400,
      );
    }

    shipperRequestUniqueId = freeSlot.shipperRequestUniqueId;
    pr = await getShipperRequestByUniqueId(
      shipperRequestUniqueId,
      bid.shipperRequestBatchId,
    );

    logger.info("Free ShipperRequest slot claimed for assignment", {
      shipperRequestUniqueId,
      batchUniqueId: bid.shipperRequestBatchId,
    });
  }

  // Prevent duplicate assignment for the same slot
  const existingAssignment = await findActiveAssignmentForSlot(
    companyBidRequestUniqueId,
    shipperRequestUniqueId,
  );
  if (existingAssignment) {
    throw new AppError(
      "This shipper request slot already has an active assignment",
      409,
    );
  }

  // ── Upsert DriverRequest — status 2 (requested): company is requesting
  //    the driver. Status advances to 4 (acceptedByShipper = all agreed)
  //    only after the driver explicitly confirms the assignment.
  const requestedStatusId = journeyStatusMap.requested;

  const driverRequestUniqueId = await upsertDriverRequest({
    driverUserUniqueId,
    newStatusId: requestedStatusId,
    originLat: pr.originLatitude,
    originLng: pr.originLongitude,
    originPlace: pr.originPlace,
  });

  // ── Create JourneyDecision at assignment time (status 2) ─────────────────
  // This is the canonical link between the shipper's ShipperRequest and
  // the driver's DriverRequest. Creating it here (not at confirmation)
  // ensures verifyDriverJourneyStatus can resolve the shipper context
  // immediately after assignment.
  const journeyDecisionUniqueId = await createJourneyDecisionForAssignment(
    shipperRequestUniqueId,
    driverRequestUniqueId,
    createdByUserUniqueId,
  );

  const assignmentUniqueId = uuidv4();
  await db().query(
    `INSERT INTO CompanyBidVehicleAssignment
      (assignmentUniqueId, companyBidRequestUniqueId, shipperRequestUniqueId,
       vehicleUniqueId, driverUserUniqueId, driverRequestUniqueId,
       assignmentStatus, journeyDecisionUniqueId, assignmentCreatedBy, assignmentCreatedAt)
     VALUES (?, ?, ?, ?, ?, ?, 'assigned', ?, ?, ?)`,
    [
      assignmentUniqueId,
      companyBidRequestUniqueId,
      shipperRequestUniqueId,
      vehicleUniqueId,
      driverUserUniqueId,
      driverRequestUniqueId,
      journeyDecisionUniqueId,
      createdByUserUniqueId,
      currentDate(),
    ],
  );

  // ── Notify the assigned driver (FCM + WebSocket) ──────────────────────────
  notifyAssignedDriver({
    driverUserUniqueId,
    assignmentUniqueId,
    driverRequestUniqueId,
    shipperRequestUniqueId,
    companyBidRequestUniqueId,
  });

  return {
    message: "success",
    data: {
      assignmentUniqueId,
      shipperRequestUniqueId,
      driverRequestUniqueId,
      journeyDecisionUniqueId,
    },
  };
};

/**
 * createBulkAssignments
 * ─────────────────────
 * Assigns multiple vehicles/drivers to different slots of a single bid batch.
 * Junior Note: This is an Atomic Operation. If one assignment fails, all fail.
 */
exports.createBulkAssignments = async (data) => {
  const { companyBidRequestUniqueId, assignments, createdByUserUniqueId } =
    data;

  // 1. Validate the bid once
  const bid = await findOne(
    "CompanyBidRequest",
    { companyBidRequestUniqueId },
    "Bid not found",
  );
  if (bid.bidStatus !== "accepted_by_shipper") {
    throw new AppError(
      "Vehicles can only be assigned after the shipper accepts the bid",
      400,
    );
  }

  // 2. Optimized: Cache status IDs for the loop
  // const acceptedStatusId = journeyStatusMap.acceptedByDriver;

  const results = [];

  // 3. Process each assignment in the bulk array
  for (const item of assignments) {
    const { shipperRequestUniqueId, vehicleUniqueId, driverUserUniqueId } =
      item;

    // Check if slot belongs to the batch — uses the dedicated service function
    const pr = await getShipperRequestByUniqueId(
      shipperRequestUniqueId,
      bid.shipperRequestBatchId,
    );

    // Prevent duplicate assignment
    const existingAssignment = await findActiveAssignmentForSlot(
      companyBidRequestUniqueId,
      shipperRequestUniqueId,
    );
    if (existingAssignment) {
      throw new AppError(
        `Slot ${shipperRequestUniqueId} already has an active assignment`,
        409,
      );
    }

    // Upsert DriverRequest — status 2 (requested): company is requesting the
    // driver. Status advances to 4 when driver confirms.
    const driverRequestUniqueId = await upsertDriverRequest({
      driverUserUniqueId,
      newStatusId: journeyStatusMap.requested,
      originLat: pr.originLatitude,
      originLng: pr.originLongitude,
      originPlace: pr.originPlace ?? "Bulk assigned",
    });

    // ── Create JourneyDecision at assignment time (status 2) ───────────────
    const journeyDecisionUniqueId = await createJourneyDecisionForAssignment(
      shipperRequestUniqueId,
      driverRequestUniqueId,
      createdByUserUniqueId,
    );

    const assignmentUniqueId = uuidv4();

    // Create Assignment
    await db().query(
      `INSERT INTO CompanyBidVehicleAssignment
        (assignmentUniqueId, companyBidRequestUniqueId, shipperRequestUniqueId,
         vehicleUniqueId, driverUserUniqueId, driverRequestUniqueId,
         assignmentStatus, journeyDecisionUniqueId, assignmentCreatedBy, assignmentCreatedAt)
       VALUES (?, ?, ?, ?, ?, ?, 'assigned', ?, ?, ?)`,
      [
        assignmentUniqueId,
        companyBidRequestUniqueId,
        shipperRequestUniqueId,
        vehicleUniqueId,
        driverUserUniqueId,
        driverRequestUniqueId,
        journeyDecisionUniqueId,
        createdByUserUniqueId,
        currentDate(),
      ],
    );

    // Notify driver (FCM + WebSocket)
    notifyAssignedDriver({
      driverUserUniqueId,
      assignmentUniqueId,
      driverRequestUniqueId,
      shipperRequestUniqueId,
      companyBidRequestUniqueId,
    });

    results.push({
      assignmentUniqueId,
      shipperRequestUniqueId,
      journeyDecisionUniqueId,
    });
  }

  return { message: "success", data: results };
};

exports.getAssignments = async (filters = {}) => {
  const { page, limit, offset } = paginate(filters);
  const clauses = ["cba.assignmentDeletedAt IS NULL"];
  const params = [];

  if (filters.assignmentUniqueId) {
    clauses.push("cba.assignmentUniqueId = ?");
    params.push(filters.assignmentUniqueId);
  }
  if (filters.companyBidRequestUniqueId) {
    clauses.push("cba.companyBidRequestUniqueId = ?");
    params.push(filters.companyBidRequestUniqueId);
  }
  if (filters.shipperRequestUniqueId) {
    clauses.push("cba.shipperRequestUniqueId = ?");
    params.push(filters.shipperRequestUniqueId);
  }
  if (filters.vehicleUniqueId) {
    clauses.push("cba.vehicleUniqueId = ?");
    params.push(filters.vehicleUniqueId);
  }
  if (filters.driverUserUniqueId) {
    clauses.push("cba.driverUserUniqueId = ?");
    params.push(filters.driverUserUniqueId);
  }
  if (filters.driverRequestUniqueId) {
    clauses.push("cba.driverRequestUniqueId = ?");
    params.push(filters.driverRequestUniqueId);
  }
  if (filters.assignmentStatus) {
    clauses.push("cba.assignmentStatus = ?");
    params.push(filters.assignmentStatus);
  }
  if (filters.journeyDecisionUniqueId) {
    clauses.push("cba.journeyDecisionUniqueId = ?");
    params.push(filters.journeyDecisionUniqueId);
  }

  const where = `WHERE ${clauses.join(" AND ")}`;
  const baseSql = `
    SELECT
      cba.*,
      u.fullName        AS driverName,
      u.phoneNumber     AS driverPhone,
      v.licensePlate,
      vt.vehicleTypeName,
      dr.journeyStatusId
    FROM CompanyBidVehicleAssignment cba
    LEFT JOIN Users u        ON cba.driverUserUniqueId     = u.userUniqueId
    LEFT JOIN Vehicle v      ON cba.vehicleUniqueId        = v.vehicleUniqueId
    LEFT JOIN VehicleTypes vt ON v.vehicleTypeUniqueId     = vt.vehicleTypeUniqueId
    LEFT JOIN DriverRequest dr ON cba.driverRequestUniqueId = dr.driverRequestUniqueId
    ${where}
  `;

  return paginatedQuery(
    `${baseSql} ORDER BY cba.assignmentCreatedAt DESC`,
    `SELECT COUNT(*) AS total FROM CompanyBidVehicleAssignment cba ${where}`,
    params,
    page,
    limit,
    offset,
  );
};

exports.updateAssignmentStatus = async (
  assignmentUniqueId,
  assignmentStatus,
  updatedBy,
  payload = {},
) => {
  // Acquire an exclusive lock on the assignment to prevent race conditions
  // (e.g. multiple concurrent "confirm" requests leading to duplicate inserts)
  const [rows] = await db().query(
    "SELECT * FROM CompanyBidVehicleAssignment WHERE assignmentUniqueId = ? LIMIT 1 FOR UPDATE",
    [assignmentUniqueId],
  );

  if (!rows || rows.length === 0) {
    throw new AppError("Assignment not found", 404);
  }

  const assignment = rows[0];

  if (assignment.assignmentDeletedAt) {
    throw new AppError("Assignment has been deleted", 400);
  }

  // ── REJECTION & CANCELLATION HANDLER (Clean up state + Notify Dispatcher) ──
  //
  // Three terminal-cancel statuses a driver can set:
  //   rejected_by_driver  — driver refused BEFORE confirming (never committed)
  //   cancelled_by_driver — driver cancelled AFTER confirming (committed but pulled out)
  //   cancelled           — legacy fallthrough, treated the same as cancelled_by_driver
  //
  // All three reset DriverRequest to waiting (status 1) so the driver is
  // available again and the slot can be reassigned.
  if (
    assignmentStatus === "rejected_by_driver" ||
    assignmentStatus === "cancelled_by_driver" ||
    assignmentStatus === "cancelled"
  ) {
    const statusId = journeyStatusMap.waiting; // always reset to 1 — driver is free again

    if (assignment.driverRequestUniqueId) {
      await db().query(
        "UPDATE DriverRequest SET journeyStatusId = ?, driverRequestUpdatedAt = ? WHERE driverRequestUniqueId = ?",
        [statusId, currentDate(), assignment.driverRequestUniqueId],
      );
    }

    // Notify the dispatcher for any cancellation so they can reassign
    const [driverRows] = await db().query(
      "SELECT fullName FROM Users WHERE userUniqueId = ?",
      [assignment.driverUserUniqueId],
    );
    const driver = driverRows?.[0];
    const isMidJobCancel =
      assignmentStatus === "cancelled_by_driver" ||
      assignmentStatus === "cancelled";

    sendFCMNotificationToUser({
      userUniqueId: assignment.assignmentCreatedBy,
      roleId: usersRoles.companyAdminRoleId,
      notification: {
        title: isMidJobCancel
          ? "Assignment Cancelled by Driver"
          : "Assignment Rejected",
        body: isMidJobCancel
          ? `Driver ${driver?.fullName || "assigned"} cancelled the freight assignment mid-job. Please reassign.`
          : `Driver ${driver?.fullName || "assigned"} has rejected the freight assignment. Please reassign.`,
      },
      data: {
        type: isMidJobCancel
          ? "assignment_cancelled_by_driver"
          : "assignment_rejected",
        assignmentUniqueId,
        shipperRequestUniqueId: assignment.shipperRequestUniqueId,
        companyBidRequestUniqueId: assignment.companyBidRequestUniqueId,
      },
    }).catch((e) =>
      logger.error("FCM failed for dispatcher notification", {
        error: e.message,
      }),
    );

    // Normalise legacy 'cancelled' to the correct ENUM value
    if (assignmentStatus === "cancelled") {
      assignmentStatus = "cancelled_by_driver";
    }

    // ── Commission evasion: driver cancelled AFTER confirming ────────────────
    // 'cancelled_by_driver' on a previously 'confirmed_by_driver' assignment
    // means the driver agreed to the job and then backed out = evasion.
    // 'rejected_by_driver' (before confirmation) is NOT evasion — just a refusal.
    // Fire post-commit so it never blocks this transaction.
    if (
      assignmentStatus === "cancelled_by_driver" &&
      assignment.assignmentStatus === "confirmed_by_driver"
    ) {
      setImmediate(async () => {
        try {
          const result = await reportDriverCommissionEvasion({
            driverUserUniqueId: assignment.driverUserUniqueId,
            reportedByUniqueId: updatedBy,
            journeyDecisionUniqueId: assignment.journeyDecisionUniqueId || null,
            reason: `Driver cancelled freight assignment after confirmation (assignment: ${assignmentUniqueId})`,
          });
          logger.info("Driver commission evasion recorded", {
            driverUserUniqueId: assignment.driverUserUniqueId,
            automaticAction: result.automaticAction,
          });
        } catch (err) {
          logger.error("Failed to record driver commission evasion", {
            driverUserUniqueId: assignment.driverUserUniqueId,
            error: err.message,
          });
        }
      });
    }
  }

  const setParts = [
    "assignmentStatus = ?",
    "assignmentUpdatedBy = ?",
    "assignmentUpdatedAt = ?",
  ];
  const vals = [assignmentStatus, updatedBy, currentDate()];

  // On driver confirmation → create JourneyDecision
  let journeyDecisionUniqueId = assignment.journeyDecisionUniqueId;

  if (assignmentStatus === "confirmed_by_driver") {
    if (assignment.assignmentStatus === "completed") {
      throw new AppError("Cannot confirm a completed assignment", 400);
    }
    if (assignment.assignmentStatus === "confirmed_by_driver") {
      return {
        message: "success",
        data: {
          assignmentStatus,
          journeyDecisionUniqueId: assignment.journeyDecisionUniqueId,
        },
      };
    }
    if (!assignment.driverRequestUniqueId) {
      throw new AppError("No DriverRequest linked to this assignment", 500);
    }

    // Uses the dedicated ShipperRequest service instead of raw SQL
    const prRow = await getShipperRequestByUniqueId(
      assignment.shipperRequestUniqueId,
    );

    const [drRows] = await db().query(
      "SELECT driverRequestId FROM DriverRequest WHERE driverRequestUniqueId = ? LIMIT 1",
      [assignment.driverRequestUniqueId],
    );
    if (!drRows || drRows.length === 0) {
      throw new AppError("Driver request not found", 404);
    }

    const jStatusId = journeyStatusMap.acceptedByShipper;

    // ── Advance the existing JourneyDecision to status 4 ───────────────────
    // JourneyDecision is created at assignment time (status 2) by
    // createJourneyDecisionForAssignment(). Here we just promote it to
    // status 4 (acceptedByShipper = all parties agreed).
    // If for any reason it doesn't exist yet (legacy record), create it now.
    const [existingDecision] = await db().query(
      "SELECT journeyDecisionUniqueId FROM JourneyDecisions WHERE driverRequestId = ? LIMIT 1",
      [drRows[0].driverRequestId],
    );

    if (existingDecision && existingDecision.length > 0) {
      journeyDecisionUniqueId = existingDecision[0].journeyDecisionUniqueId;
      // Update status from 2 (requested) → 4 (acceptedByShipper)
      await db().query(
        "UPDATE JourneyDecisions SET journeyStatusId = ?, decisionTime = ? WHERE journeyDecisionUniqueId = ?",
        [jStatusId, currentDate(), journeyDecisionUniqueId],
      );
    } else {
      // Fallback: create fresh (handles legacy assignments made before this fix)
      journeyDecisionUniqueId = uuidv4();
      await db().query(
        `INSERT INTO JourneyDecisions
          (journeyDecisionUniqueId, shipperRequestId, driverRequestId,
           journeyStatusId, decisionTime, decisionBy,
           journeyDecisionCreatedBy, journeyDecisionCreatedAt)
         VALUES (?, ?, ?, ?, ?, 'admin', ?, ?)`,
        [
          journeyDecisionUniqueId,
          prRow.shipperRequestId,
          drRows[0].driverRequestId,
          jStatusId,
          currentDate(),
          updatedBy,
          currentDate(),
        ],
      );
    }

    // ── Sync DriverRequest status and location ──────────────────────────────
    const { originLatitude, originLongitude, originPlace } = payload;
    let drUpdateQuery =
      "UPDATE DriverRequest SET journeyStatusId = ?, driverRequestUpdatedAt = ?";
    let drUpdateVals = [jStatusId, currentDate()];

    if (originLatitude !== undefined) {
      drUpdateQuery += ", originLatitude = ?";
      drUpdateVals.push(originLatitude);
    }
    if (originLongitude !== undefined) {
      drUpdateQuery += ", originLongitude = ?";
      drUpdateVals.push(originLongitude);
    }
    if (originPlace !== undefined) {
      drUpdateQuery += ", originPlace = ?";
      drUpdateVals.push(originPlace);
    }

    drUpdateQuery += " WHERE driverRequestId = ?";
    drUpdateVals.push(drRows[0].driverRequestId);

    await db().query(drUpdateQuery, drUpdateVals);

    sendFCMNotificationToUser({
      userUniqueId: assignment.driverUserUniqueId,
      roleId: usersRoles.driverRoleId,
      notification: {
        title: "Assignment confirmed",
        body: "Your freight assignment is confirmed. Prepare for pickup.",
      },
      data: {
        type: "company_assignment_confirmed",
        assignmentUniqueId,
        journeyDecisionUniqueId,
        shipperRequestUniqueId: assignment.shipperRequestUniqueId,
      },
    }).catch((e) =>
      logger.error("FCM notification failed for assignment confirmation", {
        error: e.message,
        assignmentUniqueId,
      }),
    );

    // ── Phase 1: Auto-release conflicting offers ──────────────────────────
    // Driver confirmed a company assignment → release any pending individual
    // offers so the driver isn't double-booked.
    const { releaseConflictingOffers } = require("./DriverRequest");
    await releaseConflictingOffers(
      assignment.driverUserUniqueId,
      "company",
      assignment.driverRequestUniqueId,
    );

    setParts.push("journeyDecisionUniqueId = ?");
    vals.push(journeyDecisionUniqueId);
  }

  // ── Journey progress states: sync DriverRequest.journeyStatusId ──────────
  // assignmentStatus is the primary company-specific tracking field.
  // journeyStatusId on DriverRequest is kept in sync as a cross-reference
  // to the individual-flow infrastructure (for auditing and consistency checks).
  //
  // Mapping:
  //   going_to_loading  → journeyStatusId 5 (journeyStarted: driver moving toward pickup)
  //   journey_started   → journeyStatusId 5 (journeyStarted: cargo loaded, en route — same underlying state)
  //   completed         → journeyStatusId 6 (journeyCompleted)
  //
  // Note: going_to_loading and journey_started both map to journeyStatusId=5 because
  // the individual flow only has one "in-progress" state. The company flow has more
  // granularity via assignmentStatus. journeyStatusId=5 just means "driver is moving".

  if (
    assignmentStatus === "going_to_loading" ||
    assignmentStatus === "journey_started" ||
    assignmentStatus === "completed"
  ) {
    if (!assignment.driverRequestUniqueId) {
      throw new AppError("No DriverRequest linked to this assignment", 500);
    }

    const [drRows] = await db().query(
      "SELECT driverRequestId FROM DriverRequest WHERE driverRequestUniqueId = ? LIMIT 1",
      [assignment.driverRequestUniqueId],
    );
    if (!drRows || drRows.length === 0) {
      throw new AppError("Driver request not found", 404);
    }

    const syncStatusId =
      assignmentStatus === "completed"
        ? journeyStatusMap.journeyCompleted // 6
        : journeyStatusMap.journeyStarted; // 5

    await db().query(
      "UPDATE DriverRequest SET journeyStatusId = ?, driverRequestUpdatedAt = ? WHERE driverRequestId = ?",
      [syncStatusId, currentDate(), drRows[0].driverRequestId],
    );

    // Notify the shipper about driver progress (best-effort)
    sendFCMNotificationToUser({
      userUniqueId: assignment.assignmentCreatedBy, // dispatcher / company admin
      roleId: usersRoles.companyAdminRoleId,
      notification: {
        title:
          assignmentStatus === "completed"
            ? "Delivery completed"
            : assignmentStatus === "journey_started"
              ? "Driver en route to destination"
              : "Driver heading to loading point",
        body: `Assignment ${assignmentUniqueId} status updated to: ${assignmentStatus}.`,
      },
      data: {
        type: "company_assignment_progress",
        assignmentStatus,
        assignmentUniqueId,
        companyBidRequestUniqueId: assignment.companyBidRequestUniqueId,
        shipperRequestUniqueId: assignment.shipperRequestUniqueId,
      },
    }).catch((e) =>
      logger.error("FCM failed for assignment progress notification", {
        error: e.message,
        assignmentUniqueId,
        assignmentStatus,
      }),
    );
  }

  vals.push(assignmentUniqueId);
  await db().query(
    `UPDATE CompanyBidVehicleAssignment SET ${setParts.join(", ")} WHERE assignmentUniqueId = ?`,
    vals,
  );

  // ── Batch completion check ─────────────────────────────────────────────────
  //
  // RULES:
  //   rejected_by_driver   → slot is OPEN again; dispatcher will reassign.
  //                          Do NOT change CompanyBidRequest at all.
  //   cancelled_by_driver /
  //   cancelled_by_company /
  //   cancelled_by_shipper → slot gone; only auto-complete if every other
  //                          slot is also gone / completed.
  //   completed            → check if all slots are now completed.
  //
  // The bid is marked 'completed' ONLY when every ShipperRequest slot in
  // the batch has a corresponding assignment with status = 'completed'.
  // A rejection leaves the slot available for reassignment — the bid stays
  // 'accepted_by_shipper' so the dispatcher can re-assign.
  //
  if (assignmentStatus === "rejected_by_driver") {
    // Slot is free again. No bid-level change needed.
    logger.info("Assignment rejected — slot open for reassignment", {
      assignmentUniqueId,
      companyBidRequestUniqueId: assignment.companyBidRequestUniqueId,
    });
  } else if (assignmentStatus === "completed") {
    // Check if EVERY slot in the batch now has a 'completed' assignment.
    const [[{ totalSlots }]] = await db().query(
      `SELECT COUNT(*) AS totalSlots
       FROM ShipperRequest
       WHERE shipperRequestBatchId = (
         SELECT shipperRequestBatchId FROM CompanyBidRequest
         WHERE companyBidRequestUniqueId = ? LIMIT 1
       )
         AND shipperRequestDeletedAt IS NULL`,
      [assignment.companyBidRequestUniqueId],
    );

    const [[{ completedSlots }]] = await db().query(
      `SELECT COUNT(*) AS completedSlots
       FROM CompanyBidVehicleAssignment
       WHERE companyBidRequestUniqueId = ?
         AND assignmentStatus = 'completed'
         AND assignmentDeletedAt IS NULL`,
      [assignment.companyBidRequestUniqueId],
    );

    if (completedSlots >= totalSlots && totalSlots > 0) {
      await db().query(
        `UPDATE CompanyBidRequest
         SET bidStatus = 'completed', companyBidRequestUpdatedAt = ?
         WHERE companyBidRequestUniqueId = ?`,
        [currentDate(), assignment.companyBidRequestUniqueId],
      );
      logger.info("Batch auto-completed: all slots delivered", {
        companyBidRequestUniqueId: assignment.companyBidRequestUniqueId,
        completedSlots,
        totalSlots,
      });
    }
  }

  return {
    message: "success",
    data: {
      assignmentStatus,
      journeyDecisionUniqueId:
        journeyDecisionUniqueId || assignment.journeyDecisionUniqueId,
    },
  };
};

/**
 * autoAssignBatch
 * ───────────────
 * The "Auto-Assigner" intelligence layer. This function automatically maps available
 * fleet (vehicle/driver pairs) to unassigned slots within a single accepted bid.
 *
 * ### HOW IT WORKS (Technical Workflow):
 * 1. **Slot Discovery**: Finds all `ShipperRequest` items in the batch that are
 *    NOT yet assigned in `CompanyBidVehicleAssignment`.
 * 2. **Availability Check**: Queries the company's active fleet. A driver/vehicle
 *    is only "Available" if they have no active trip where the status is NOT
 *    one of (completed, cancelled, rejected).
 * 3. **1-to-1 Mapping**: Matches slots to the next available driver-vehicle pair.
 * 4. **Partial Support**: If the fleet is smaller than the total slots, it
 *    assigns as many as possible and returns a summary of the remainder.
 * 5. **Atomicity**: Executed inside a database transaction to ensure batch integrity.
 *
 * @param {Object} data - Payload
 * @param {string} data.companyBidRequestUniqueId - The ID of the winning bid.
 * @param {string} data.createdByUserUniqueId - The dispatcher's user ID.
 * @returns {Promise<Object>} Summary of assigned vs unassigned counts and record pointers.
 */
exports.autoAssignBatch = async (data) => {
  const { companyBidRequestUniqueId, createdByUserUniqueId } = data;

  // 1. Fetch bid details to get batch and company
  const bid = await findOne(
    "CompanyBidRequest",
    { companyBidRequestUniqueId },
    "Bid not found",
  );
  if (bid.bidStatus !== "accepted_by_shipper") {
    throw new AppError(
      "Auto-assignment can only be performed after a bid is accepted by the shipper",
      400,
    );
  }

  const { shipperRequestBatchId, companyUniqueId } = bid;

  // 2. Find Unassigned Slots for this Batch
  // Only consider slots that are still FREE (acceptedByShipper = not yet driven,
  // not cancelled). After a partial cancellation, cancelled slots have a
  // terminal journeyStatusId — filtering by status excludes them cleanly
  // without needing to inspect cancellation records separately.
  const [unassignedSlots] = await db().query(
    `SELECT pr.shipperRequestUniqueId, pr.originLatitude, pr.originLongitude, pr.originPlace
     FROM ShipperRequest pr
     WHERE pr.shipperRequestBatchId = ? 
       AND pr.shipperRequestDeletedAt IS NULL
       AND pr.journeyStatusId = ?
       AND NOT EXISTS (
         SELECT 1 FROM CompanyBidVehicleAssignment cba
         WHERE cba.shipperRequestUniqueId = pr.shipperRequestUniqueId
           AND cba.companyBidRequestUniqueId = ?
           AND cba.assignmentDeletedAt IS NULL
           AND cba.assignmentStatus NOT IN ('rejected_by_driver','cancelled_by_company','cancelled_by_shipper','cancelled_by_driver')
       )`,
    [shipperRequestBatchId, journeyStatusMap.acceptedByShipper, companyBidRequestUniqueId],
  );

  if (unassignedSlots.length === 0) {
    return {
      message: "success",
      data: "All slots in this batch are already assigned.",
    };
  }

  // 3. Find Available Fleet (Vehicles + Drivers)
  //
  // Two-layer exclusion:
  //   Layer 1 (global):  Skip drivers/vehicles that have any ACTIVE assignment
  //                      anywhere (not completed/cancelled/rejected).
  //   Layer 2 (per-batch): Skip drivers who already REJECTED this specific batch.
  //                        Once a driver declines, they should not be re-offered
  //                        the same job even after auto-reassign is triggered.
  //                        Note: only the driver is blocked, NOT the vehicle —
  //                        the vehicle can still be paired with a different driver.
  const [availableFleet] = await db().query(
    `SELECT cv.vehicleUniqueId, vd.driverUserUniqueId, v.vehicleTypeUniqueId
     FROM CompanyVehicle cv
     JOIN Vehicle v ON cv.vehicleUniqueId = v.vehicleUniqueId
     JOIN VehicleDriver vd ON cv.vehicleUniqueId = vd.vehicleUniqueId
     WHERE cv.companyUniqueId = ?
       AND cv.assignmentStatus = 'active' AND cv.companyVehicleDeletedAt IS NULL
       AND vd.assignmentStatus = 'active'
       -- Layer 1: no active trip elsewhere
       AND NOT EXISTS (
         SELECT 1 FROM CompanyBidVehicleAssignment cba
         WHERE (cba.vehicleUniqueId = cv.vehicleUniqueId OR cba.driverUserUniqueId = vd.driverUserUniqueId)
           AND cba.assignmentStatus NOT IN ('completed', 'cancelled_by_company', 'cancelled_by_shipper', 'cancelled_by_driver', 'rejected_by_driver')
           AND cba.assignmentDeletedAt IS NULL
       )
       -- Layer 2: driver has not already rejected THIS batch
        --  AND NOT EXISTS (
        --  SELECT 1 FROM CompanyBidVehicleAssignment cba_rej
        --  WHERE cba_rej.driverUserUniqueId = vd.driverUserUniqueId
        --    AND cba_rej.companyBidRequestUniqueId = ?
        --    AND cba_rej.assignmentStatus = 'rejected_by_driver'
        --    AND cba_rej.assignmentDeletedAt IS NULL
       -- )`,
    [companyUniqueId, companyBidRequestUniqueId],
  );

  // 4. Handle Case: Fleet is busy but slots need assignment
  if (availableFleet.length === 0) {
    return {
      message: "success",
      data: {
        summary: `Successfully auto-assigned 0 slots. ${unassignedSlots.length} slots remain unassigned due to limited fleet availability.`,
        assignedCount: 0,
        unassignedCount: unassignedSlots.length,
        assignments: [],
      },
    };
  }

  // 5. Perform Mapping (Partial Assignment Support)
  const assignmentsToCreate = [];
  const limit = Math.min(unassignedSlots.length, availableFleet.length);

  for (let i = 0; i < limit; i++) {
    assignmentsToCreate.push({
      shipperRequestUniqueId: unassignedSlots[i].shipperRequestUniqueId,
      vehicleUniqueId: availableFleet[i].vehicleUniqueId,
      driverUserUniqueId: availableFleet[i].driverUserUniqueId,
      origin: {
        lat: unassignedSlots[i].originLatitude,
        lng: unassignedSlots[i].originLongitude,
        place: unassignedSlots[i].originPlace,
      },
    });
  }

  // 5. Execute Assignments in bulk
  // Status 2 (requested): company is requesting the driver.
  // Status advances to 4 (all agreed) when driver explicitly confirms.
  const results = [];

  for (const item of assignmentsToCreate) {
    // Upsert DriverRequest — status 2 (requested): company is requesting the
    // driver. Status advances to 4 (all agreed) when driver confirms.
    const driverRequestUniqueId = await upsertDriverRequest({
      driverUserUniqueId: item.driverUserUniqueId,
      newStatusId: journeyStatusMap.requested,
      originLat: item.origin.lat,
      originLng: item.origin.lng,
      originPlace: item.origin.place ?? "Auto-assigned",
    });

    // ── Create JourneyDecision at assignment time (status 2) ───────────────
    const journeyDecisionUniqueId = await createJourneyDecisionForAssignment(
      item.shipperRequestUniqueId,
      driverRequestUniqueId,
      createdByUserUniqueId,
    );

    const assignmentUniqueId = uuidv4();

    // Create Assignment
    await db().query(
      `INSERT INTO CompanyBidVehicleAssignment
        (assignmentUniqueId, companyBidRequestUniqueId, shipperRequestUniqueId,
         vehicleUniqueId, driverUserUniqueId, driverRequestUniqueId,
         assignmentStatus, journeyDecisionUniqueId, assignmentCreatedBy, assignmentCreatedAt)
       VALUES (?, ?, ?, ?, ?, ?, 'assigned', ?, ?, ?)`,
      [
        assignmentUniqueId,
        companyBidRequestUniqueId,
        item.shipperRequestUniqueId,
        item.vehicleUniqueId,
        item.driverUserUniqueId,
        driverRequestUniqueId,
        journeyDecisionUniqueId,
        createdByUserUniqueId,
        currentDate(),
      ],
    );

    // Notify driver (FCM + WebSocket)
    notifyAssignedDriver({
      driverUserUniqueId: item.driverUserUniqueId,
      assignmentUniqueId,
      driverRequestUniqueId,
      shipperRequestUniqueId: item.shipperRequestUniqueId,
      companyBidRequestUniqueId,
    });

    results.push({
      assignmentUniqueId,
      shipperRequestUniqueId: item.shipperRequestUniqueId,
      journeyDecisionUniqueId,
    });
  }

  const unassignedCount = unassignedSlots.length - results.length;
  const summary =
    unassignedCount > 0
      ? `Successfully auto-assigned ${results.length} slots. ${unassignedCount} slots remain unassigned due to limited fleet availability.`
      : `Successfully auto-assigned all ${results.length} slots.`;

  return {
    message: "success",
    data: {
      summary,
      assignedCount: results.length,
      unassignedCount,
      assignments: results,
    },
  };
};

exports.deleteAssignment = async (assignmentUniqueId, deletedBy) => {
  const [res] = await db().query(
    `UPDATE CompanyBidVehicleAssignment
     SET assignmentDeletedAt = ?, assignmentDeletedBy = ?
     WHERE assignmentUniqueId = ? AND assignmentDeletedAt IS NULL`,
    [currentDate(), deletedBy, assignmentUniqueId],
  );
  if (res.affectedRows === 0) {
    throw new AppError("Assignment not found or already deleted", 404);
  }
  return { message: "success", data: "Assignment deleted" };
};

"use strict";

const { v4: uuidv4 } = require("uuid");
const { currentDate } = require("../Utils/CurrentDate");
const AppError = require("../Utils/AppError");
const {
  db,
  findOne,
  paginate,
  paginatedQuery,
} = require("./CompanyHelper.service");
const logger = require("../Utils/logger");
const {
  reportCompanyCommissionEvasion,
} = require("./CommissionEvasion.service");
const { sendFCMNotificationToUser } = require("./Firebase.service");
const { sendSocketIONotificationToCompany } = require("../Utils/Notifications");
const messageTypes = require("../Utils/MessageTypes");
const { journeyStatusMap, usersRoles } = require("../Utils/ListOfSeedData");

/**
 * ### CORE LOGIC - Submit a Freight Bid
 * Processes a transport company's bid for a shipper's request batch.
 *
 * **Junior Note: Source of Truth Pattern**
 * To ensure data integrity, this function automatically fetches the vehicle type and
 * vehicle count from the `ShipperRequestBatch` table. This prevents the frontend
 * from accidentally sending mismatched data.
 *
 * **Important Rules:**
 * 1. Only 'Approved' companies can bid.
 * 2. Companies can't bid on work targeted at *other* specific companies.
 * 3. **Full Batch Only**: By default, companies bid on the *entire* batch.
 *
 * > [!TIP]
 * > **HOW TO ENABLE PARTIAL BIDDING (Future Restore):**
 * > If you need to allow companies to bid on only part of a batch:
 * > 1. Update `Validations/CompanyBid.schema.js` to make `numberOfVehiclesOffered` required.
 * > 2. Remove the line `const finalCount = totalVehicles;`.
 * > 3. Un-comment the validation: `if (numberOfVehiclesOffered > totalVehicles) { throw ... }`.
 * > 4. Use `numberOfVehiclesOffered` as the `finalCount` in the INSERT query.
 *
 * @param {Object} data - The payload containing bid details.
 * @param {string} data.shipperRequestBatchId - The UUID that groups the shipper's requests.
 * @param {string} data.companyUniqueId - The ID of the bidding fleet.
 * @param {string} data.bidSubmittedByUserUniqueId - The User ID of the dispatcher.
 * @param {number} [data.numberOfVehiclesOffered] - Optional; defaults to batch total.
 * @param {string} [data.vehicleTypeUniqueId] - Optional; defaults to batch requirement.
 * @returns {Promise<Object>} Success message.
 */
exports.submitBid = async (data) => {
  const {
    shipperRequestBatchId,
    companyUniqueId,
    bidSubmittedByUserUniqueId,
    vehicleTypeUniqueId,
    proposedCostPerVehicle,
    proposedTotalCost,
    proposedShippingDate,
    proposedDeliveryDate,
    bidNotes,
  } = data;

  // Company must be approved (registration-level check)
  const company = await findOne(
    "TransportCompany",
    { companyUniqueId, isDeleted: 0 },
    "Company not found",
  );
  if (company.approvalStatus !== "approved") {
    throw new AppError(
      `Company is not eligible to bid. Registration status: ${company.approvalStatus}`,
      400,
    );
  }

  // Company must not have an active ban (compliance-level check)
  // CompanyBan is the single source of truth for ban history — approvalStatus is never modified by bans.
  const [[activeBan]] = await db().query(
    `SELECT companyBanUniqueId, banReason, banExpiresAt
     FROM CompanyBan
     WHERE companyUniqueId = ? AND isActive = TRUE AND banExpiresAt > NOW()
     LIMIT 1`,
    [companyUniqueId],
  );
  if (activeBan) {
    const expiresOn = new Date(activeBan.banExpiresAt)
      .toISOString()
      .slice(0, 10);
    throw new AppError(
      `Company is currently suspended from bidding until ${expiresOn}. Reason: ${activeBan.banReason}`,
      403,
    );
  }

  // 1. Verify the batch exists and get its metadata
  const [batchRows] = await db().query(
    `SELECT totalVehicles, vehicleTypeUniqueId, requestMode, targetCompanyUniqueId, shipperUserUniqueId 
     FROM ShipperRequestBatch 
     WHERE batchUniqueId = ? AND batchDeletedAt IS NULL LIMIT 1`,
    [shipperRequestBatchId],
  );
  if (!batchRows || batchRows.length === 0) {
    throw new AppError("Shipper request batch not found", 404);
  }

  const {
    totalVehicles,
    requestMode,
    targetCompanyUniqueId,
    shipperUserUniqueId,
  } = batchRows[0];

  // --- SOURCE OF TRUTH: We prioritize the batch's required vehicle type ---
  const finalVehicleTypeUniqueId =
    batchRows[0].vehicleTypeUniqueId || vehicleTypeUniqueId;

  // 2. Check company-targeting
  if (
    requestMode === "company_target" &&
    targetCompanyUniqueId !== null &&
    targetCompanyUniqueId !== companyUniqueId
  ) {
    throw new AppError("This batch is targeted at a different company", 403);
  }

  // 2b. Reject new bids if a bid has already been accepted for this batch.
  //     Once the shipper selects a winner, the bidding window closes.
  const [acceptedBids] = await db().query(
    `SELECT companyBidRequestUniqueId, companyUniqueId
     FROM CompanyBidRequest
     WHERE shipperRequestBatchId = ?
       AND bidStatus = 'accepted_by_shipper'
       AND companyBidRequestDeletedAt IS NULL
     LIMIT 1`,
    [shipperRequestBatchId],
  );
  if (acceptedBids.length > 0) {
    throw new AppError(
      "Bidding is closed for this batch — a bid has already been accepted by the shipper",
      409,
    );
  }

  // 3. Verify the batch has actual requests — only relevant for individual_target batches.
  //    company_target batches intentionally have zero ShipperRequest rows at bid time;
  //    rows are bulk-created when the shipper accepts the winning bid.
  if (requestMode !== "company_target") {
    const [countRows] = await db().query(
      `SELECT COUNT(*) AS batchCount
       FROM ShipperRequest
       WHERE shipperRequestBatchId = ? AND shipperRequestDeletedAt IS NULL`,
      [shipperRequestBatchId],
    );
    const actualRequestCount = Number(countRows?.[0]?.batchCount ?? 0);
    if (actualRequestCount === 0) {
      throw new AppError("This batch contains no individual requests", 400);
    }
  }

  // 4. Determine final vehicle count (Full Batch Logic)
  // To restore partial bidding, use the user input instead of totalVehicles.
  const finalCount = totalVehicles;

  /* 
  // PARTIAL BID RESTORATION LOGIC:
  if (numberOfVehiclesOffered > totalVehicles) {
     throw new AppError(`Cannot bid for ${numberOfVehiclesOffered} when batch only needs ${totalVehicles}`, 400);
  }
  const finalCount = numberOfVehiclesOffered; 
  */

  // One bid per company per batch
  const [existing] = await db().query(
    "SELECT companyBidRequestId FROM CompanyBidRequest WHERE companyUniqueId = ? AND shipperRequestBatchId = ? AND companyBidRequestDeletedAt IS NULL",
    [companyUniqueId, shipperRequestBatchId],
  );
  if (existing.length > 0) {
    throw new AppError(
      "This company has already submitted a bid for this batch",
      409,
    );
  }


  // Note: Capacity validation removed per user request.
  // Companies can now bid even if requested vehicles exceed their current free fleet,
  // as they may fulfill the request in multiple rounds.

  const journeyStatusId = journeyStatusMap.waiting;

  const companyBidRequestUniqueId = uuidv4();
  const calculatedTotalCost =
    proposedTotalCost ?? proposedCostPerVehicle * finalCount;

  await db().query(
    `INSERT INTO CompanyBidRequest
      (companyBidRequestUniqueId, shipperRequestBatchId, companyUniqueId,
       bidSubmittedByUserUniqueId, numberOfVehiclesOffered, vehicleTypeUniqueId,
       proposedCostPerVehicle, proposedTotalCost, proposedShippingDate,
       proposedDeliveryDate, bidNotes, bidStatus, journeyStatusId,
       companyBidRequestCreatedBy, companyBidRequestCreatedAt)
     VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 'submitted', ?, ?, ?)`,
    [
      companyBidRequestUniqueId,
      shipperRequestBatchId,
      companyUniqueId,
      bidSubmittedByUserUniqueId,
      finalCount,
      finalVehicleTypeUniqueId,
      proposedCostPerVehicle,
      calculatedTotalCost,
      proposedShippingDate ?? null,
      proposedDeliveryDate ?? null,
      bidNotes ?? null,
      journeyStatusId,
      bidSubmittedByUserUniqueId,
      currentDate(),
    ],
  );
  // 🔔 Notify Shipper via WebSocket
  if (shipperUserUniqueId) {
    // Get shipper phone number for socket identifier
    const [shipperRows] = await db().query(
      "SELECT phoneNumber FROM Users WHERE userUniqueId = ?",
      [shipperUserUniqueId],
    );

    if (shipperRows?.[0]?.phoneNumber) {
      const {
        sendSocketIONotificationToShipper,
      } = require("../Utils/Notifications");
      sendSocketIONotificationToShipper({
        phoneNumber: shipperRows[0].phoneNumber,
        message: {
          messageTypes: messageTypes.company_bid_submitted,
          notification: {
            title: "New Company Bid",
            body: `${company.companyName} has submitted a bid for your freight.`,
          },
          data: {
            companyBidRequestUniqueId,
            companyName: company.companyName,
            shipperRequestBatchId,
            proposedTotalCost: calculatedTotalCost,
          },
        },
      }).catch((e) =>
        logger.error("WebSocket notification to shipper failed in submitBid", {
          error: e.message,
          shipperUserUniqueId,
        }),
      );
    }
  }

  return { message: "success", data: { companyBidRequestUniqueId } };
};

/**
 * ### DISCOVERY LOGIC - Find Available Bids
 * Fetches batches targeted at the company or open to all companies.
 *
 * **Junior Note: SQL Optimization Corner**
 * 1. **`ONLY_FULL_GROUP_BY` Workaround**: In modern MySQL, `GROUP BY` is strict. To select a full
 *    set of data (`SELECT *`) while grouping by a batch ID, we first use a subquery to find
 *    the `MIN(shipperRequestId)` for each matching batch. Then we join back to those specific IDs.
 * 2. **Hiding Existing Bids**: We use a `NOT EXISTS` block. This ensures that once your company
 *    submits a bid, the request automatically disappears from your "Available" board to prevent
 *    double-bidding.
 * 3. **Open Bids**: We check for `targetCompanyUniqueId IS NULL`. This allows shippers to broadcast
 *    work to all transport fleets at once.
 *
 * @param {string} userUniqueId - The authenticated dispatcher seeking work.
 * @param {Object} filters - Pagination and search filters.
 * @returns {Promise<Object>} A paginated object with `data` (list) and `pagination` (total).
 */
exports.getAvailableRequests = async (companyUniqueId, filters = {}) => {
  const { page, limit, offset } = paginate(filters);

  // 2. Fetch Requests from the optimized Metadata table (O(N) PERFORMANCE)
  const activeStatusIds = [
    journeyStatusMap.requested,
    journeyStatusMap.waiting,
  ];

  const filterClauses = [
    "b.batchDeletedAt IS NULL",
    "b.requestMode = 'company_target'",
    "(b.targetCompanyUniqueId = ? OR b.targetCompanyUniqueId IS NULL)",
    "b.journeyStatusId IN (?)",
    `NOT EXISTS (
      SELECT 1 FROM CompanyBidRequest cbr 
      WHERE cbr.shipperRequestBatchId = b.batchUniqueId 
      AND cbr.companyUniqueId = ? AND cbr.companyBidRequestDeletedAt IS NULL
    )`,
  ];
  const params = [companyUniqueId, activeStatusIds, companyUniqueId];
  const filterWhere = `WHERE ${filterClauses.join(" AND ")}`;

  // baseSql: No subqueries, no Group By! Pure performance.
  const baseSql = `
    SELECT b.*, 
           b.batchUniqueId AS shipperRequestBatchId, -- backwards compatibility
           u.fullName AS shipperName,
           u.phoneNumber AS shipperPhone,
           vt.vehicleTypeName, js.journeyStatusName
    FROM ShipperRequestBatch b
    LEFT JOIN Users u ON b.shipperUserUniqueId = u.userUniqueId
    LEFT JOIN VehicleTypes vt ON b.vehicleTypeUniqueId = vt.vehicleTypeUniqueId
    LEFT JOIN JourneyStatus js ON b.journeyStatusId = js.journeyStatusId
    ${filterWhere}
  `;

  const countSql = `
    SELECT COUNT(*) AS total 
    FROM ShipperRequestBatch b
    ${filterWhere}
  `;

  return paginatedQuery(
    `${baseSql} ORDER BY b.batchCreatedAt DESC`,
    countSql,
    params,
    page,
    limit,
    offset,
  );
};

/**
 * ### UNIFIED GROUPED VIEW - Batches with Nested Offers
 * Works for both Shippers and Company Dispatchers.
 *
 * - **Shipper**: Shows their freight batches, each with ALL company offers inside `offers[]`.
 * - **Company**: Shows batches they bid on, each with their own offer inside `offers[]`.
 *
 * Offers are sorted cheapest first so shippers can compare prices at a glance.
 *
 * @param {Object} scope - { shipperUserUniqueId } or { companyUniqueId }
 * @param {Object} filters - Pagination and optional bidStatus/shipperRequestBatchId.
 * @returns {Promise<Object>} Paginated list of batches with nested offers.
 */
exports.getGroupedBids = async (scope = {}, filters = {}) => {
  const { shipperUserUniqueId, companyUniqueId } = scope;
  const { page, limit, offset } = paginate(filters);

  // ── 1. Build the batch WHERE clause ──────────────────────────────────────
  const batchClauses = ["b.batchDeletedAt IS NULL", "b.requestMode = 'company_target'"];
  const batchParams = [];

  if (shipperUserUniqueId) {
    // Shippers see their own batches.
    // When offer-level filters are provided, we add an EXISTS guard so that
    // batches with 0 matching offers are never returned — same pattern as
    // the company path below.
    batchClauses.push("b.shipperUserUniqueId = ?");
    batchParams.push(shipperUserUniqueId);

    if (filters.bidStatus || filters.isCancellationSeenByCompany) {
      const existsClauses = [
        "cbr.shipperRequestBatchId = b.batchUniqueId",
        "cbr.companyBidRequestDeletedAt IS NULL",
      ];

      if (filters.bidStatus) {
        existsClauses.push("cbr.bidStatus = ?");
        batchParams.push(filters.bidStatus);
      }
      if (filters.isCancellationSeenByCompany) {
        existsClauses.push("cbr.isCancellationSeenByCompany = ?");
        batchParams.push(filters.isCancellationSeenByCompany);
      }

      batchClauses.push(
        `EXISTS (
          SELECT 1 FROM CompanyBidRequest cbr
          WHERE ${existsClauses.join(" AND ")}
        )`,
      );
    }
  } else if (companyUniqueId) {
    // Companies see only batches they have a matching bid on.
    // The EXISTS subquery mirrors the same filters applied to offers (Step 2)
    // so that batches with 0 matching offers are never returned.
    const existsClauses = [
      "cbr.shipperRequestBatchId = b.batchUniqueId",
      "cbr.companyUniqueId = ?",
      "cbr.companyBidRequestDeletedAt IS NULL",
    ];
    batchParams.push(companyUniqueId);

    if (filters.bidStatus) {
      existsClauses.push("cbr.bidStatus = ?");
      batchParams.push(filters.bidStatus);
    }
    if (filters.isCancellationSeenByCompany) {
      existsClauses.push("cbr.isCancellationSeenByCompany = ?");
      batchParams.push(filters.isCancellationSeenByCompany);
    }

    batchClauses.push(
      `EXISTS (
        SELECT 1 FROM CompanyBidRequest cbr
        WHERE ${existsClauses.join(" AND ")}
      )`,
    );
  }

  if (filters.shipperRequestBatchId) {
    batchClauses.push("b.batchUniqueId = ?");
    batchParams.push(filters.shipperRequestBatchId);
  }

  const batchWhere = `WHERE ${batchClauses.join(" AND ")}`;

  const [batches] = await db().query(
    `SELECT b.batchUniqueId,
            b.batchUniqueId AS shipperRequestBatchId,
            b.batchId,
            b.originPlace, b.destinationPlace,
            b.shippableItemName, b.shippableItemQtyInQuintal,
            b.totalVehicles, b.shippingCost AS batchShippingCost,
            b.shippingDate AS batchShippingDate, b.deliveryDate AS batchDeliveryDate,
            b.journeyStatusId, b.requestMode, b.batchCreatedAt,
            js.journeyStatusName, vt.vehicleTypeName,
            u.fullName AS shipperName
     FROM ShipperRequestBatch b
     LEFT JOIN JourneyStatus js ON b.journeyStatusId = js.journeyStatusId
     LEFT JOIN VehicleTypes vt ON b.vehicleTypeUniqueId = vt.vehicleTypeUniqueId
     LEFT JOIN Users u ON b.shipperUserUniqueId = u.userUniqueId
     ${batchWhere}
     ORDER BY b.batchCreatedAt DESC
     LIMIT ? OFFSET ?`,
    [...batchParams, limit, offset],
  );

  const [[{ total }]] = await db().query(
    `SELECT COUNT(*) AS total FROM ShipperRequestBatch b ${batchWhere}`,
    batchParams,
  );

  if (!batches || batches.length === 0) {
    return {
      message: "success",
      data: [],
      pagination: { page, limit, total: 0, totalPages: 0 },
    };
  }

  // ── 2. Fetch all matching offers in ONE query (avoids N+1) ───────────────
  const batchIds = batches.map((b) => b.batchUniqueId);

  const offerClauses = [
    "cbr.shipperRequestBatchId IN (?)",
    "cbr.companyBidRequestDeletedAt IS NULL",
  ];
  const offerParams = [batchIds];

  // Companies only see their own offer; shippers see everyone's
  if (companyUniqueId) {
    offerClauses.push("cbr.companyUniqueId = ?");
    offerParams.push(companyUniqueId);
  }
  if (filters.bidStatus) {
    offerClauses.push("cbr.bidStatus = ?");
    offerParams.push(filters.bidStatus);
  }
  if (filters.isCancellationSeenByCompany) {
    offerClauses.push("cbr.isCancellationSeenByCompany = ?");
    offerParams.push(filters.isCancellationSeenByCompany);
  }

  const [offers] = await db().query(
    `SELECT cbr.companyBidRequestUniqueId,
            cbr.shipperRequestBatchId,
            cbr.companyUniqueId,
            cbr.bidSubmittedByUserUniqueId,
            cbr.numberOfVehiclesOffered,
            cbr.proposedCostPerVehicle,
            cbr.proposedTotalCost,
            cbr.proposedShippingDate,
            cbr.proposedDeliveryDate,
            cbr.bidNotes,
            cbr.bidStatus,
            cbr.bidStatusUpdatedAt,
            cbr.isCancellationSeenByCompany,
            cbr.companyBidRequestCreatedAt,
            tc.companyName, tc.companyPhone, tc.companyEmail,
            vt.vehicleTypeName AS offeredVehicleTypeName,
            u.fullName AS submittedByName,
            (SELECT COUNT(*) FROM CompanyVehicle cv
             WHERE cv.companyUniqueId = cbr.companyUniqueId
               AND cv.assignmentStatus = 'active'
               AND cv.companyVehicleDeletedAt IS NULL
            ) AS companyFleetSize
     FROM CompanyBidRequest cbr
     LEFT JOIN TransportCompany tc ON cbr.companyUniqueId = tc.companyUniqueId
     LEFT JOIN VehicleTypes vt ON cbr.vehicleTypeUniqueId = vt.vehicleTypeUniqueId
     LEFT JOIN Users u ON cbr.bidSubmittedByUserUniqueId = u.userUniqueId
     WHERE ${offerClauses.join(" AND ")}
     ORDER BY cbr.proposedTotalCost ASC`,
    offerParams,
  );

  // ── 3. Group offers under each batch using a Map (O(N)) ──────────────────
  const offersByBatchId = new Map();
  for (const offer of offers) {
    if (!offersByBatchId.has(offer.shipperRequestBatchId)) {
      offersByBatchId.set(offer.shipperRequestBatchId, []);
    }
    offersByBatchId.get(offer.shipperRequestBatchId).push(offer);
  }

  const grouped = batches.map((batch) => ({
    ...batch,
    offerCount: (offersByBatchId.get(batch.batchUniqueId) || []).length,
    offers: offersByBatchId.get(batch.batchUniqueId) || [],
  }));

  return {
    message: "success",
    data: grouped,
    pagination: {
      page,
      limit,
      total,
      totalPages: Math.ceil(total / limit),
    },
  };
};

/**
 * ### DASHBOARD LOGIC - Get Dashboard Counts
 * Fetches total counts for different bid categories (badges/notifications).
 *
 * **Junior Note: "The Dashboard Speed Pattern"**
 * Mobile apps shouldn't load all 50 shipping requests just to show a "4" badge. This method
 * runs multiple lightweight `COUNT` operations in parallel. This is the **Best Practice** for
 * low-latency landing pages.
 *
 * **Counts Provided:**
 * - `available`: New work ready for discovery.
 * - `submitted`: Active bids waiting for shipper response.
 * - `accepted`: Winning bids ready for you to assign drivers/vehicles.
 *
 * @param {string} userUniqueId - The user identity to derive the company membership.
 * @returns {Promise<Object>} An object with structured counts for UI badges.
 */
exports.getBidsSummary = async (companyUniqueId) => {
  if (!companyUniqueId) {
    throw new AppError("companyUniqueId is required", 400);
  }
  // 2. Count Available (matching discovery boards filters)
  const activeStatusIds = [
    journeyStatusMap.requested,
    journeyStatusMap.waiting,
  ];
  const [availableRes] = await db().query(
    `SELECT COUNT(*) AS total 
     FROM ShipperRequestBatch b
     WHERE b.batchDeletedAt IS NULL
       AND b.requestMode = 'company_target'
       AND (b.targetCompanyUniqueId = ? OR b.targetCompanyUniqueId IS NULL)
       AND b.journeyStatusId IN (?)
       AND NOT EXISTS (
         SELECT 1 FROM CompanyBidRequest cbr 
         WHERE cbr.shipperRequestBatchId = b.batchUniqueId 
         AND cbr.companyUniqueId = ? AND cbr.companyBidRequestDeletedAt IS NULL
       )`,
    [companyUniqueId, activeStatusIds, companyUniqueId],
  );

  // 3. Count Submitted (Pending shipper response)
  const [submittedRes] = await db().query(
    `SELECT COUNT(*) AS total FROM CompanyBidRequest 
     WHERE companyUniqueId = ? AND bidStatus = 'submitted' 
       AND companyBidRequestDeletedAt IS NULL`,
    [companyUniqueId],
  );

  // 4. Count Accepted (Shipper approved, ready for dispatch)
  const [acceptedRes] = await db().query(
    `SELECT COUNT(*) AS total FROM CompanyBidRequest 
     WHERE companyUniqueId = ? AND bidStatus = 'accepted_by_shipper' 
       AND companyBidRequestDeletedAt IS NULL`,
    [companyUniqueId],
  );

  return {
    message: "success",
    data: {
      available: availableRes[0]?.total || 0,
      submitted: submittedRes[0]?.total || 0,
      accepted: acceptedRes[0]?.total || 0,
      total:
        (availableRes[0]?.total || 0) +
        (submittedRes[0]?.total || 0) +
        (acceptedRes[0]?.total || 0),
    },
  };
};

/**
 * ### GATEWAY LOGIC - The Bid Access Point
 * Routes unified requests to the specialized 'Available' or 'Summary' logic.
 *
 * **Junior Note: Route Cleanliness**
 * Instead of creating 5 different routes, we use a single `GET /` with a `target` query param.
 * This keeps the API surface clean and similar to how a folder/tab system works on the frontend.
 *
 * @param {Object} filters - Raw query parameters from the request.
 * @param {string} [userUniqueId] - Optional ID for authenticated scoping.
 * @returns {Promise<Object>} Any format requested via the `target` parameter.
 */
exports.getBids = async (filters = {}, userUniqueId = null, roleId = null) => {
  if (!userUniqueId) {
    throw new AppError("Authentication required", 401);
  }
  const isAdmin =
    roleId === usersRoles.adminRoleId ||
    roleId === usersRoles.supperAdminRoleId;
  const isShipper = roleId === usersRoles.shipperRoleId;
  const isCompanyAdmin =
    roleId === usersRoles.companyAdminRoleId ||
    roleId === usersRoles.companyDispatchRoleId;
  let resolvedCompanyUniqueId = null;
  let resolvedShipperUserUniqueId = null;

  if (isAdmin) {
    // Admins can target a specific company or shipper
    resolvedCompanyUniqueId = filters.companyUniqueId || null;
    resolvedShipperUserUniqueId = filters.shipperUserUniqueId || null;
  } else if (isShipper) {
    // Shippers can only see bids for their own batches
    resolvedShipperUserUniqueId = userUniqueId;
  } else if (isCompanyAdmin) {
    // Standard users (Dispatchers) MUST resolve to their own company
    const [membership] = await db().query(
      `SELECT companyUniqueId FROM CompanyMembership WHERE userUniqueId = ? AND isActive = 1 AND membershipDeletedAt IS NULL`,
      [userUniqueId],
    );
    if (!membership || membership.length === 0) {
      throw new AppError(
        "User is not an active member of any transport company",
        403,
      );
    }
    //if filters.companyUniqueId is provided, check if the user is a member of that company
    if (filters?.companyUniqueId) {
      const isMember = membership.some(
        (m) => m?.companyUniqueId === filters?.companyUniqueId,
      );
      if (!isMember) {
        throw new AppError(
          "Access Denied: You are not an active member of the specified company",
          403,
        );
      }
      resolvedCompanyUniqueId = filters?.companyUniqueId;
    } else {
      //if filters.companyUniqueId is not provided, check if the user is a member of only one company
      if (membership?.length === 1) {
        resolvedCompanyUniqueId = membership?.[0]?.companyUniqueId;
      } else {
        //if the user is a member of multiple companies, throw an error
        throw new AppError(
          "You belong to multiple companies. Please provide companyUniqueId in your query to specify which company you are fetching data for.",
          400,
        );
      }
    }
  }
  //get all company bids for the resolved companyUniqueId

  if (filters?.target === "summary") {
    if (!resolvedCompanyUniqueId) {
      throw new AppError("companyUniqueId is required for summary mode", 400);
    }
    return exports.getBidsSummary(resolvedCompanyUniqueId);
  }
  // if filters.target is available, get available requests, get biddable requests only when target is company and
  if (filters?.target === "available") {
    if (!resolvedCompanyUniqueId) {
      throw new AppError("companyUniqueId is required for available mode", 400);
    }
    return exports.getAvailableRequests(resolvedCompanyUniqueId, filters);
  }

  // Default (grouped) — works for shippers, companies, and admins
  return exports.getGroupedBids(
    {
      shipperUserUniqueId: resolvedShipperUserUniqueId,
      companyUniqueId: resolvedCompanyUniqueId,
    },
    filters,
  );
};

/**
 * ### STATE MACHINE - Multi-step Status Updates
 * Updates the bid status and manages the lifecycle of the linked ShipperRequest.
 *
 * **Junior Note: Synchronization Logic**
 * - When you accept a bid, the *Request* also updates its status so no one else can take it.
 * - When a bid is rejected/cancelled, the *Request* falls back to 'waiting' so other
 *   companies can see it again.
 * - This function also triggers **FCM Notifications** to notify the dispatcher instantly
 *   about the shipper's decision.
 *
 * @param {string} companyBidRequestUniqueId - The ID of the bid record to update.
 * @param {string} bidStatus - The new desired status (e.g., 'accepted_by_shipper').
 * @param {string} updatedBy - The admin/shipper ID performing the action.
 */
/**
 * Updates the status of a company bid (e.g., Accepting, Rejecting, or Cancelling).
 *
 * ### CRITICAL: Consistency & Atomicity (for Junior Developers):
 * This function handles the most sensitive state transitions in the bidding system.
 * Because it affects both the `CompanyBidRequest` and `ShipperRequest` tables,
 * it MUST be executed inside a database transaction to prevent \"partial updates\"
 * if the server crashes.
 *
 * #### The \"Race Condition\" Shield (Part E):
 * When a shipper accepts a company bid (`accepted_by_shipper`), we perform two vital steps:
 * 1. **Locking**: We use `FOR UPDATE` on all requests in the batch. This \"locks\" the
 *    rows in MySQL so that an individual driver cannot claim them while this
 *    function is running.
 * 2. **Verification**: After locking, we re-check if any request was already
 *    claimed by someone else just milliseconds prior. If so, we \"Hard Fail\"
 *    (Conflict 409) rather than overwriting someone else's work.
 *
 * @param {string} companyBidRequestUniqueId - The ID of the bid being updated.
 * @param {string} bidStatus - The new status (e.g., 'accepted_by_shipper', 'rejected_by_shipper').
 * @param {string} updatedBy - The User Unique ID of the person making the change.
 * @throws {AppError} 404 - If the bid is not found.
 * @throws {AppError} 409 - If a consistency conflict is detected (someone already claimed the freight).
 * @returns {Promise<Object>} Success message.
 */
exports.updateBidStatus = async (
  companyBidRequestUniqueId,
  bidStatus,
  updatedBy,
) => {
  const bid = await findOne(
    "CompanyBidRequest",
    { companyBidRequestUniqueId },
    "Bid not found",
  );
  if (bid.companyBidRequestDeletedAt) {
    throw new AppError("Bid has been deleted", 400);
  }

  const [res] = await db().query(
    `UPDATE CompanyBidRequest
     SET bidStatus = ?, bidStatusUpdatedAt = ?, bidStatusUpdatedBy = ?,
         companyBidRequestUpdatedBy = ?, companyBidRequestUpdatedAt = ?
     WHERE companyBidRequestUniqueId = ?`,
    [
      bidStatus,
      currentDate(),
      updatedBy,
      updatedBy,
      currentDate(),
      companyBidRequestUniqueId,
    ],
  );
  if (res.affectedRows === 0) {
    throw new AppError("Bid update failed", 500);
  }

  let newPRStatus = null;
  if (bidStatus === "accepted_by_shipper") {
    // ── COMPANY-TARGET vs INDIVIDUAL-TARGET handling ────────────────────────
    //
    // company_target (bulk-create on acceptance):
    //   No PR rows exist yet. We NOW bulk-create all N ShipperRequest rows
    //   at the moment the shipper accepts the winning company bid.
    //   Each row starts in `acceptedByShipper` status with no driver assigned.
    //   The dispatcher then calls createAssignment() to pair each row with a driver.
    //
    // individual_target (eager):
    //   PRs already exist from createShipperRequest. Lock and verify they're
    //   still free, then update their status.

    // 1. Check if PRs already exist for this batch
    const [existingPRs] = await db().query(
      `SELECT shipperRequestId, journeyStatusId
       FROM ShipperRequest
       WHERE shipperRequestBatchId = ?
         AND shipperRequestDeletedAt IS NULL
       FOR UPDATE`,
      [bid.shipperRequestBatchId],
    );

    if (existingPRs.length === 0) {
      // ── COMPANY-TARGET PATH: Bulk-create all N ShipperRequest rows now ──
      // Fetch full batch metadata needed to populate each row
      const [[batch]] = await db().query(
        `SELECT * FROM ShipperRequestBatch WHERE batchUniqueId = ? LIMIT 1`,
        [bid.shipperRequestBatchId],
      );
      if (!batch) {
        throw new AppError("Batch not found during acceptance", 409);
      }

      const { v4: uuidv4 } = require("uuid");
      const formatDateToReadable = require("../Utils/FormatDateToReadable");
      const totalSlots = bid.numberOfVehiclesOffered;

      // Build a multi-row INSERT for all N slots in one query
      const placeholders = Array(totalSlots).fill(
        "(?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
      ).join(", ");

      const values = [];
      for (let i = 0; i < totalSlots; i++) {
        values.push(
          uuidv4(),                                          // shipperRequestUniqueId
          batch.shipperUserUniqueId,                        // userUniqueId (shipper)
          batch.batchUniqueId,                              // shipperRequestBatchId
          batch.vehicleTypeUniqueId,                        // vehicleTypeUniqueId
          journeyStatusMap.acceptedByShipper,               // journeyStatusId — born accepted, no driver yet
          batch.requestMode,                                // requestMode
          batch.targetCompanyUniqueId,                      // targetCompanyUniqueId
          batch.originLatitude,
          batch.originLongitude,
          batch.originPlace,
          batch.destinationLatitude,
          batch.destinationLongitude,
          batch.destinationPlace,
          batch.shippableItemName,
          batch.shippableItemQtyInQuintal,
          batch.shippingDate ? formatDateToReadable(batch.shippingDate) : null,
          batch.deliveryDate ? formatDateToReadable(batch.deliveryDate) : null,
          batch.shippingCost,
          updatedBy,                                        // shipperRequestCreatedBy (shipper who accepted)
          usersRoles.shipperRoleId,                         // shipperRequestCreatedByRoleId
          currentDate(),                                    // shipperRequestCreatedAt
        );
      }

      await db().query(
        `INSERT INTO ShipperRequest
          (shipperRequestUniqueId, userUniqueId, shipperRequestBatchId,
           vehicleTypeUniqueId, journeyStatusId, requestMode, targetCompanyUniqueId,
           originLatitude, originLongitude, originPlace,
           destinationLatitude, destinationLongitude, destinationPlace,
           shippableItemName, shippableItemQtyInQuintal,
           shippingDate, deliveryDate, shippingCost,
           shipperRequestCreatedBy, shipperRequestCreatedByRoleId, shipperRequestCreatedAt)
         VALUES ${placeholders}`,
        values,
      );

      // Update the batch header status
      await db().query(
        `UPDATE ShipperRequestBatch
         SET journeyStatusId = ?, batchUpdatedAt = ?
         WHERE batchUniqueId = ?`,
        [journeyStatusMap.acceptedByShipper, currentDate(), bid.shipperRequestBatchId],
      );

      logger.info(
        `company_target bid accepted — ${totalSlots} ShipperRequest rows created`,
        {
          batchUniqueId: bid.shipperRequestBatchId,
          bidUniqueId: companyBidRequestUniqueId,
          totalVehicles: totalSlots,
        },
      );
    } else {
      // ── INDIVIDUAL-TARGET EAGER PATH: PRs already exist → verify state ──
      const freeRequests = existingPRs.filter(
        (r) =>
          r.journeyStatusId === journeyStatusMap.waiting ||
          r.journeyStatusId === journeyStatusMap.requested ||
          r.journeyStatusId === journeyStatusMap.acceptedByDriver,
      );

      if (freeRequests.length < bid.numberOfVehiclesOffered) {
        const alreadyClaimed = existingPRs.length - freeRequests.length;
        throw new AppError(
          `Consistency Conflict: Only ${freeRequests.length} of ${bid.numberOfVehiclesOffered} requested vehicles are still available. ${alreadyClaimed} individual driver(s) have already been accepted for this freight.`,
          409,
        );
      }

      // Update existing PRs to accepted status
      await db().query(
        `UPDATE ShipperRequest
         SET journeyStatusId = ?
         WHERE shipperRequestBatchId = ? AND shipperRequestDeletedAt IS NULL`,
        [journeyStatusMap.acceptedByShipper, bid.shipperRequestBatchId],
      );
    }

    newPRStatus = null; // Already handled above — skip the generic UPDATE below
  } else if (
    bidStatus === "cancelled_by_company" ||
    bidStatus === "rejected_by_shipper" ||
    bidStatus === "expired"
  ) {
    newPRStatus = journeyStatusMap.waiting;

    // ── Commission evasion check ───────────────────────────────────────────
    // A company cancelling AFTER the shipper already accepted = evasion.
    // The previous bidStatus is still in `bid` (fetched before the UPDATE).
    // Fire post-commit (setImmediate) so it does NOT block this transaction.
    if (
      bidStatus === "cancelled_by_company" &&
      bid.bidStatus === "accepted_by_shipper"
    ) {
      setImmediate(async () => {
        try {
          const result = await reportCompanyCommissionEvasion({
            companyUniqueId: bid.companyUniqueId,
            reportedByUniqueId: updatedBy,
            journeyDecisionUniqueId: companyBidRequestUniqueId,
            reason: `Company cancelled freight bid after shipper acceptance (bid: ${companyBidRequestUniqueId})`,
          });
          logger.info("Commission evasion recorded for company", {
            companyUniqueId: bid.companyUniqueId,
            automaticAction: result.automaticAction,
          });
        } catch (err) {
          logger.error("Failed to record commission evasion", {
            companyUniqueId: bid.companyUniqueId,
            error: err.message,
          });
        }
      });
    }
  }

  if (newPRStatus !== null) {
    await db().query(
      `UPDATE ShipperRequest
       SET journeyStatusId = ?
       WHERE shipperRequestBatchId = ? AND shipperRequestDeletedAt IS NULL`,
      [newPRStatus, bid.shipperRequestBatchId],
    );
  }

  const notificationMap = {
    accepted_by_shipper: {
      title: "Bid accepted",
      body: "The shipper has accepted your company's freight bid.",
    },
    rejected_by_shipper: {
      title: "Bid rejected",
      body: "The shipper has rejected your company's freight bid.",
    },
    cancelled_by_company: {
      title: "Bid cancelled",
      body: "Your company's bid has been cancelled.",
    },
    expired: {
      title: "Bid expired",
      body: "Your company's bid has expired without a response.",
    },
  };
  const notif = notificationMap[bidStatus];
  if (notif && bid.bidSubmittedByUserUniqueId) {
    sendFCMNotificationToUser({
      userUniqueId: bid.bidSubmittedByUserUniqueId,
      roleId: usersRoles.driverRoleId,
      notification: notif,
      data: {
        type: "company_bid_status_update",
        bidStatus,
        companyBidRequestUniqueId,
        shipperRequestBatchId: bid.shipperRequestBatchId,
      },
    }).catch((e) =>
      logger.error("FCM notification failed for bid status update", {
        error: e.message,
      }),
    );

    // 🔔 Real-time WebSocket Notification
    const socketMessageTypeMap = {
      accepted_by_shipper: messageTypes.company_bid_accepted,
      rejected_by_shipper: messageTypes.company_bid_rejected,
      cancelled_by_company: messageTypes.company_bid_cancelled,
    };

    const socketMsgType = socketMessageTypeMap[bidStatus];
    if (socketMsgType) {
      sendSocketIONotificationToCompany({
        companyUniqueId: bid.companyUniqueId,
        message: {
          messageTypes: socketMsgType,
          notification: notif,
          data: {
            bidStatus,
            companyBidRequestUniqueId,
            shipperRequestBatchId: bid.shipperRequestBatchId,
          },
        },
      }).catch((e) =>
        logger.error("WebSocket notification failed for company bid status", {
          error: e.message,
          companyUniqueId: bid.companyUniqueId,
        }),
      );
    }
  }

  return { message: "success", data: "Bid status updated" };
};

exports.deleteBid = async (companyBidRequestUniqueId, deletedBy) => {
  const [res] = await db().query(
    `UPDATE CompanyBidRequest
     SET companyBidRequestDeletedAt = ?, companyBidRequestDeletedBy = ?
     WHERE companyBidRequestUniqueId = ? AND companyBidRequestDeletedAt IS NULL`,
    [currentDate(), deletedBy, companyBidRequestUniqueId],
  );
  if (res.affectedRows === 0) {
    throw new AppError("Bid not found or already deleted", 404);
  }
  return { message: "success", data: "Bid deleted" };
};

// ── Mark cancellation as seen by company ──────────────────────────────────────
// Called when a company dispatcher opens/acknowledges the cancelled bid.
// Mirrors DriverRequest.isCancellationByShipperSeenByDriver pattern.
exports.markCancellationAsSeen = async ({
  companyBidRequestUniqueId,
  userUniqueId,
}) => {
  // 1. Fetch the bid
  const [[bid]] = await db().query(
    `SELECT cbr.companyBidRequestId,
            cbr.companyUniqueId,
            cbr.bidStatus,
            cbr.isCancellationSeenByCompany
       FROM CompanyBidRequest cbr
      WHERE cbr.companyBidRequestUniqueId = ?
        AND cbr.companyBidRequestDeletedAt IS NULL
      LIMIT 1`,
    [companyBidRequestUniqueId],
  );

  if (!bid) {
    throw new AppError("Bid not found", 404);
  }

  // 2. Verify the caller belongs to the company that owns the bid
  const [[membership]] = await db().query(
    `SELECT 1 FROM CompanyMembership
      WHERE companyUniqueId = ?
        AND userUniqueId = ?
        AND isActive = 1
        AND membershipDeletedAt IS NULL
      LIMIT 1`,
    [bid.companyUniqueId, userUniqueId],
  );

  if (!membership) {
    throw new AppError(
      "Unauthorized: you are not a member of this company",
      403,
    );
  }

  // 3. Guard: only mark if the bid is actually cancelled and unseen
  if (bid.bidStatus !== "cancelled_by_company") {
    throw new AppError(
      "This bid has not been cancelled — nothing to mark as seen",
      400,
    );
  }
  if (bid.isCancellationSeenByCompany === "seen by company") {
    return { message: "success", data: "Already marked as seen" };
  }

  // 4. Mark as seen
  await db().query(
    `UPDATE CompanyBidRequest
        SET isCancellationSeenByCompany = 'seen by company',
            companyBidRequestUpdatedAt  = ?
      WHERE companyBidRequestUniqueId = ?`,
    [currentDate(), companyBidRequestUniqueId],
  );

  return { message: "success", data: "Cancellation marked as seen" };
};

