    if (ownerUserUniqueId && ownerUserUniqueId !== "all") {
      queryWhereParts.push(`${userField} = ?`);
      queryParams.push(ownerUserUniqueId);
    }

    // journey status condition
    queryWhereParts.push(`Journey.journeyStatusId = ?`);
