      JOIN JourneyDecisions ON JourneyDecisions.journeyDecisionUniqueId = Journey.journeyDecisionUniqueId
      JOIN ${joinTable} ON ${joinCondition}
      JOIN Users ON ${joinTable}.userUniqueId = Users.userUniqueId
