  await step("Admin: login + get JWT", async () => {
    state.adminToken = await getToken(SUPER_ADMIN_PHONE, 6);
    return "JWT acquired";
  });

  await step(
    "Admin: migrate DB (CREATE IF NOT EXISTS all tables)",
